#!/bin/bash
localhostIP4=$(/sbin/ip -o -4 addr list eth0 | awk '{print $4}' | cut -d/ -f1) && sudo rm -rf /var/lib/docker && sudo ln -s /home/docker/ /var/lib/docker && version=$(curl -s https://artifactory-espoo2.int.net.nokia.com:443/artifactory/tts-binaries-releases-local/dcap-basic/releases/ | grep "href=" | tail -1 | cut -c 10-17) && curl https://artifactory-espoo2.int.net.nokia.com:443/artifactory/tts-binaries-releases-local/dcap-basic/releases/$version/dcap_basic_installer.$version.sh --output dcap_basic_installer.latest.sh && sudo UTE_CLOUD=1 bash dcap_basic_installer.latest.sh $localhostIP4 && echo You can access the DCAP in a web browser at: https://$localhostIP4:9443
